using EddaStore.Filters;
using System.Security.Claims;
using EddaStore.Services.Interfaces;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
namespace EddaStore.Controllers;

[Authorize]
[ServiceFilter(typeof(RequireCompleteProfileFilter))]
public class CartController(ICartService cartService) : Controller { public async Task<IActionResult> Index(CancellationToken ct) => View(await cartService.GetAsync(UserId(), ct)); [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> Add(Guid productId, int quantity = 1, string? returnUrl = null, CancellationToken ct = default) { try { await cartService.AddAsync(UserId(), productId, quantity, ct); TempData["Success"] = "تمت إضافة المنتج إلى السلة."; return RedirectToAction(nameof(Index)); } catch (KeyNotFoundException) { return NotFound(); } catch (Exception ex) when (ex is ArgumentException or InvalidOperationException) { TempData["Error"] = ex.Message; } return Url.IsLocalUrl(returnUrl) ? LocalRedirect(returnUrl) : RedirectToAction(nameof(Index)); } [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> Update(Guid productId, int quantity, CancellationToken ct) { try { await cartService.UpdateAsync(UserId(), productId, quantity, ct); } catch (Exception ex) when (ex is KeyNotFoundException or InvalidOperationException) { TempData["Error"] = ex is InvalidOperationException ? ex.Message : "تعذر تحديث السلة."; } return RedirectToAction(nameof(Index)); } [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> Remove(Guid productId, CancellationToken ct) { try { await cartService.RemoveAsync(UserId(), productId, ct); TempData["Success"] = "تم حذف المنتج من السلة."; } catch (KeyNotFoundException) { return NotFound(); } return RedirectToAction(nameof(Index)); } private Guid UserId() => Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!); }
